import 'package:flutter/material.dart';
import '../core/services/api_client.dart';
import '../core/theme/app_theme.dart';
class PromotionsScreen extends StatefulWidget{const PromotionsScreen({super.key});@override State<PromotionsScreen>createState()=>_PromotionsScreenState();}
class _PromotionsScreenState extends State<PromotionsScreen>{List<dynamic>items=[];bool loading=true;String?error;@override void initState(){super.initState();load();}Future<void>load()async{try{final d=await ApiClient.get('/promotions');items=d['data']??[];}catch(e){error=e.toString();}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext c){return Scaffold(appBar:AppBar(title:const Text('Promotions')),body:loading?const Center(child:CircularProgressIndicator()):error!=null?Center(child:Text(error!)):RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.all(16),itemCount:items.length,itemBuilder:(_,i){final p=items[i];return Card(margin:const EdgeInsets.only(bottom:14),clipBehavior:Clip.antiAlias,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Container(height:110,width:double.infinity,decoration:const BoxDecoration(gradient:LinearGradient(colors:[AppTheme.pale,Color(0xFFDDF5F5)])),child:const Icon(Icons.local_offer_rounded,size:54,color:AppTheme.teal)),Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(p['title']??'',style:const TextStyle(fontSize:18,fontWeight:FontWeight.w800)),if((p['description']??'').toString().isNotEmpty)Padding(padding:const EdgeInsets.only(top:6),child:Text(p['description'])),if(p['coupon_code']!=null)Padding(padding:const EdgeInsets.only(top:10),child:Chip(label:Text('CODE: ${p['coupon_code']}')))]))]));}));}}
